// TestGenerateVectors writes the Go-generated files in vectors/mls: Go's
// crypto/hpke and crypto/mldsa output for Swift and Rust to open and verify,
// and a group Go founded and committed to, for them to follow. Run with
// MOQOM_MLS_GENERATE=1 go test -run TestGenerateVectors. Randomness is
// cryptotest's fixed source, so regenerating changes nothing.
func TestGenerateVectors(t *testing.T) {
	if os.Getenv("MOQOM_MLS_GENERATE") != "1" {
		t.Skip("MOQOM_MLS_GENERATE is not set")
	}
	cryptotest.SetGlobalRandom(t, 0x6d6f716f6d)
	crypto := generateCrypto(t)
	group := generateGroup(t)
	writeVectors(t, "mls-crypto-go.json",
		"RFC 9420 §5 SignWithLabel and EncryptWithLabel as Go's crypto/mldsa and crypto/hpke produce them, which is what checks the Swift and Rust HPKE compositions: suite 0xF0AC (KEM 0x0042, KDF 0x0003, AEAD 0x0002). Same fields as mls-crypto.json.",
		crypto)
	writeVectors(t, "mls-group-go.json",
		"A group in suite 0xF0AC founded and committed to by Go, followed by one member whose private keys are given. Same fields and rules as mls-group.json.",
		group)
}

func writeVectors(t *testing.T, file, description string, cases []map[string]any) {
	t.Helper()
	data, err := json.MarshalIndent(map[string]any{
		"library":     "moqom-mls",
		"description": description,
		"source":      "Generated by moqom-mls (Go, standard library): go/mls/generate_test.go",
		"cases":       cases,
	}, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(vectorDir, file), append(data, '\n'), 0o644); err != nil {
		t.Fatal(err)
	}
}

func fixed(name string, n int) []byte {
	var out []byte
	for block := byte(0); len(out) < n; block++ {
		sum := sha512.Sum512(append([]byte("moqom-mls "+name), block))
		out = append(out, sum[:]...)
	}
	return out[:n]
}

func flipped(data []byte, offset int) []byte {
	out := append([]byte(nil), data...)
	if offset < 0 {
		offset += len(out)
	}
	out[offset] ^= 1
	return out
}

func with(base map[string]any, fields map[string]any) map[string]any {
	out := map[string]any{}
	for k, v := range base {
		out[k] = v
	}
	for k, v := range fields {
		out[k] = v
	}
	return out
}

func generateCrypto(t *testing.T) []map[string]any {
	suite := SuiteMLDSA
	seed := fixed("go signature seed", 32)
	key, err := mldsa.NewPrivateKey(mldsa.MLDSA87(), seed)
	if err != nil {
		t.Fatal(err)
	}
	content := fixed("go content", 64)
	signature, err := suite.SignWithLabel(seed, "KeyPackageTBS", content)
	if err != nil {
		t.Fatal(err)
	}
	signed := map[string]any{
		"op": "sign_with_label", "seed_hex": hex.EncodeToString(seed), "public_key_hex": hex.EncodeToString(key.PublicKey().Bytes()),
		"label": "KeyPackageTBS", "content_hex": hex.EncodeToString(content), "signature_hex": hex.EncodeToString(signature),
	}

	kemSeed := fixed("go kem seed", 64)
	kem, err := mlkem.NewDecapsulationKey1024(kemSeed)
	if err != nil {
		t.Fatal(err)
	}
	context := fixed("go context", 40)
	plaintext := fixed("go joiner secret", 64)
	sealed, err := suite.EncryptWithLabel(kem.EncapsulationKey().Bytes(), "Welcome", context, plaintext)
	if err != nil {
		t.Fatal(err)
	}
	encrypted := map[string]any{
		"op": "encrypt_with_label", "seed_hex": hex.EncodeToString(kemSeed), "public_key_hex": hex.EncodeToString(kem.EncapsulationKey().Bytes()),
		"label": "Welcome", "context_hex": hex.EncodeToString(context), "plaintext_hex": hex.EncodeToString(plaintext),
		"kem_output_hex": hex.EncodeToString(sealed.KEMOutput), "ciphertext_hex": hex.EncodeToString(sealed.Ciphertext),
	}
	return []map[string]any{
		with(signed, map[string]any{"name": "go-sign-with-label"}),
		with(signed, map[string]any{"name": "go-sign-with-label-tampered", "signature_hex": hex.EncodeToString(flipped(signature, 0)), "error": "bad-signature"}),
		with(encrypted, map[string]any{"name": "go-encrypt-with-label"}),
		with(encrypted, map[string]any{"name": "go-encrypt-with-label-tampered", "kem_output_hex": hex.EncodeToString(flipped(sealed.KEMOutput, 0)), "error": "decryption-failed"}),
	}
}

func state(t *testing.T, g *Group) map[string]any {
	members := []any{}
	for _, leaf := range g.Members() {
		if leaf == nil {
			members = append(members, nil)
		} else {
			members = append(members, string(leaf.Identity))
		}
	}
	return map[string]any{
		"epoch": g.Epoch(), "own_leaf": g.OwnLeaf(), "members": members,
		"epoch_authenticator_hex": hex.EncodeToString(g.EpochAuthenticator()),
		"exporters": []map[string]any{
			{"label": SFrameExporterLabel, "context_hex": "", "length": 32, "out_hex": hex.EncodeToString(must[[]byte](t)(g.Exporter(SFrameExporterLabel, nil, 32)))},
			{"label": "MOQOM direct offer", "context_hex": "", "length": 32, "out_hex": hex.EncodeToString(must[[]byte](t)(g.Exporter("MOQOM direct offer", nil, 32)))},
		},
	}
}

func member(b *KeyPackageBundle) map[string]any {
	return map[string]any{
		"key_package_hex":        hex.EncodeToString(b.KeyPackage.Encode()),
		"init_private_hex":       hex.EncodeToString(b.initPrivate),
		"encryption_private_hex": hex.EncodeToString(b.encryptionPrivate),
		"signature_private_hex":  hex.EncodeToString(b.signaturePrivate),
	}
}

func must[T any](t *testing.T) func(T, error) T {
	return func(v T, err error) T {
		t.Helper()
		if err != nil {
			t.Fatal(err)
		}
		return v
	}
}

func advance(t *testing.T, g *Group, m *CommitMessage) *Group {
	t.Helper()
	next, removed, err := g.Process(m)
	if err != nil || removed {
		t.Fatalf("process: removed %v, %v", removed, err)
	}
	return next
}

func generateGroup(t *testing.T) []map[string]any {
	bundle := must[*KeyPackageBundle](t)
	group := must[*Group](t)
	commit := must[*PendingCommit](t)
	groupID := []byte("acme/room-7")

	alice := group(CreateGroup(groupID, bundle(GenerateKeyPackage("alice/a", SuiteMLDSA))))
	bob := bundle(GenerateKeyPackage("bob/b", SuiteMLDSA))
	carol := bundle(GenerateKeyPackage("carol/c", SuiteMLDSA))
	dave := bundle(GenerateKeyPackage("dave/d", SuiteMLDSA))
	var steps []map[string]any

	addBob := commit(alice.Commit([]*KeyPackage{bob.KeyPackage}, nil))
	alice = addBob.Next
	bobGroup := group(Join(addBob.Welcome, bob))
	steps = append(steps, map[string]any{"welcome_hex": hex.EncodeToString(addBob.Welcome.Encode()), "expect": state(t, bobGroup)})

	addTwo := commit(alice.Commit([]*KeyPackage{carol.KeyPackage, dave.KeyPackage}, nil))
	alice = addTwo.Next
	bobGroup = advance(t, bobGroup, addTwo.Message)
	steps = append(steps, map[string]any{"commit_hex": hex.EncodeToString(addTwo.Message.Encode()), "expect": state(t, bobGroup)})
	carolGroup := group(Join(addTwo.Welcome, carol))

	update := commit(carolGroup.Commit(nil, nil))
	carolGroup = update.Next
	alice = advance(t, alice, update.Message)
	bobGroup = advance(t, bobGroup, update.Message)
	steps = append(steps, map[string]any{"commit_hex": hex.EncodeToString(update.Message.Encode()), "expect": state(t, bobGroup)})

	daveLeaf, _ := alice.LeafOf("dave/d")
	removeDave := commit(alice.Commit(nil, []uint32{daveLeaf}))
	carolGroup = advance(t, carolGroup, removeDave.Message)
	bobGroup = advance(t, bobGroup, removeDave.Message)
	steps = append(steps, map[string]any{"commit_hex": hex.EncodeToString(removeDave.Message.Encode()), "expect": state(t, bobGroup)})

	bobLeaf, _ := carolGroup.LeafOf("bob/b")
	removeBob := commit(carolGroup.Commit(nil, []uint32{bobLeaf}))
	if _, removed, err := bobGroup.Process(removeBob.Message); err != nil || !removed {
		t.Fatalf("bob was not removed: %v", err)
	}
	steps = append(steps, map[string]any{"commit_hex": hex.EncodeToString(removeBob.Message.Encode()), "removed": true})

	return []map[string]any{{
		"name": "go-founded-bob-follows", "cipher_suite": int(SuiteMLDSA), "group_id_hex": hex.EncodeToString(groupID),
		"member": member(bob), "steps": steps,
	}}
}
